import json
import urllib.request
import websocket

# Get chrome://extensions tab
targets = json.loads(urllib.request.urlopen("http://localhost:1337/json/list").read())
ext_target = next(t for t in targets if t["url"].startswith("chrome://extensions"))
ws = websocket.create_connection(ext_target["webSocketDebuggerUrl"])

def send(method, params=None, _id=[0]):
    _id[0] += 1
    ws.send(json.dumps({"id": _id[0], "method": method, "params": params or {}}))
    while True:
        msg = json.loads(ws.recv())
        if msg.get("id") == _id[0]:
            return msg

# Wait for page to be ready, then evaluate JS to get loaded extensions
send("Page.enable")
send("Runtime.enable")
res = send("Runtime.evaluate", {
    "expression": """
      (async () => {
        // chrome://extensions exposes chrome.developerPrivate
        return await new Promise(resolve => {
          chrome.developerPrivate.getExtensionsInfo({}, items => {
            resolve(items.map(i => ({name: i.name, id: i.id, location: i.location, version: i.version, enabled: i.state === 'ENABLED'})));
          });
        });
      })()
    """,
    "awaitPromise": True,
    "returnByValue": True
})
print(json.dumps(res, indent=2))
ws.close()
